package main

import (
	"fmt"
	"net/url"
	"strings"
)

func getURLForQuery(apiURL, userID string) *string {
	if userID == "" {
		return nil
	}

	// Validate user ID: alphanumeric only
	if !strings.ContainsFunc(userID, func(r rune) bool {
		return (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9')
	}) {
		return nil
	}

	// Escape the user ID for URL
	escapedUserID := url.PathEscape(userID)
	completeURL := apiURL + "/" + escapedUserID

	return &completeURL
}

func main() {
	// Test cases
	fmt.Println(getURLForQuery("https://example.com/api/user", "aBc123")) // Expected: "https://example.com/api/user/aBc123"
	fmt.Println(getURLForQuery("https://example.com/api/user", ""))         // Expected: <nil>
	fmt.Println(getURLForQuery("https://example.com/api/user", "user@123")) // Expected: <nil> (invalid due to @)
}

